import { FC, HTMLAttributes, useEffect } from 'react';
import { useTranslation } from 'react-i18next';
import { useParams } from 'react-router-dom';

import cn from 'classnames';

import {
	CreateSourceForm,
	ESourceTypes,
	prepareArbitragerSourceData,
	prepareBloggerSourceData,
	prepareBloggerUrls,
	prepareWebsiteSourceData,
	useGetSourceQuery,
	useSourceSlice,
} from 'entities/Source';
import { useNotFoundError } from 'shared/hooks';
import { OverlayLoader, Page, PageTitle } from 'shared/ui';

import styles from './EditSource.module.scss';

interface IEditSourceProps extends HTMLAttributes<HTMLDivElement> {}

export const EditSource: FC<IEditSourceProps> = ({ className, ...props }) => {
	const { t } = useTranslation();
	const {
		setWebsiteValues,
		setBloggerValues,
		setAllBloggerUrls,
		//bloggerUrls,
		setArbitrationValues,
		setType,
		clearValues,
	} = useSourceSlice();
	const params = useParams<{ id: string }>();
	const { data, error, isFetching } = useGetSourceQuery(params?.id || '', { skip: !params?.id });

	useNotFoundError(error);

	useEffect(() => {
		if (data?.uuid) {
			setType(data.type);

			switch (data.type) {
				case ESourceTypes.WEBSITE:
					setWebsiteValues(prepareWebsiteSourceData(data));
					return;
				case ESourceTypes.BLOGGER:
					setBloggerValues(prepareBloggerSourceData(data));
					setAllBloggerUrls(prepareBloggerUrls(data.influencer_data.urls));

					return;
				case ESourceTypes.ARBITRATION:
					setArbitrationValues(prepareArbitragerSourceData(data));
					return;
			}
		} else {
			clearValues();
		}
	}, [data]); // eslint-disable-line

	useEffect(() => {
		return () => {
			clearValues();
		};
	}, []); // eslint-disable-line

	return (
		<Page {...props} className={cn(className, styles.createSource)}>
			<PageTitle>
				{t('Редактирование площадки')} {data?.name}
			</PageTitle>

			{isFetching && <OverlayLoader />}

			<CreateSourceForm className={styles.form} source={data} />
		</Page>
	);
};

export default EditSource;
